"""Private MoE implementation selection."""

from __future__ import annotations

from dataclasses import replace

import torch

from kestrel_kernels.cute_moe.config import (
    get_cute_moe_config,
    has_cute_moe_config,
    is_block_scheduled_fp8_kernel,
    resolve_cute_moe_exact_capacity,
    resolve_cute_moe_prefill_capacity,
)
from kestrel_kernels.moe.api import (
    MoeCapacity,
    MoeExpertWeights,
    MoeHandle,
    MoeLoraState,
    MoeSpec,
)
from kestrel_kernels.moe.errors import FP8_MOE_REQUIRES_COMPACT_CONFIG
from kestrel_kernels.moe.legacy.ops import LegacyPaddedOps
from kestrel_kernels.moe.legacy.padded import prepare_legacy_padded
from kestrel_kernels.moe.compact import prepare_compact_moe
from kestrel_kernels.moe.warpgemv import prepare_warpgemv

_MoeHandleCacheKey = tuple[torch.device, MoeSpec, MoeCapacity]
_MOE_HANDLE_CACHE: dict[_MoeHandleCacheKey, MoeHandle] = {}


def _gelu_only_kernel(kernel_type: str, *, dtype: str) -> bool:
    return (
        kernel_type == "warpgemv" and dtype != "bf16"
    ) or (kernel_type == "tcgen" and dtype == "fp8")


def _device_sm(device: torch.device) -> int:
    major, minor = torch.cuda.get_device_capability(device)
    return int(major) * 10 + int(minor)


def prepare(
    spec: MoeSpec,
    capacity: MoeCapacity,
    *,
    device: torch.device | str,
) -> MoeHandle:
    """Prepare a cached MoE handle.

    Each backend maps the logical request to its physical workspace/kernel
    capacity. Cached handles own mutable workspace buffers and are intended
    for sequential reuse.
    """
    device = torch.device(device)
    if device.type == "cuda" and device.index is None and torch.cuda.is_available():
        device = torch.device("cuda", torch.cuda.current_device())

    if device.type == "cuda":
        capacity = _resolve_cuda_capacity(spec, capacity)
    elif device.type == "mps" and capacity.mode == "prefill":
        capacity = _resolve_power_of_two_prefill_capacity(capacity)

    key = (device, spec, capacity)
    handle = _MOE_HANDLE_CACHE.get(key)
    if handle is None:
        handle = _prepare_fresh(spec, capacity, device=device)
        _MOE_HANDLE_CACHE[key] = handle
    return handle


def _resolve_cuda_capacity(spec: MoeSpec, capacity: MoeCapacity) -> MoeCapacity:
    config_dtype = "fp8" if spec.weight_format == "fp8_e4m3" else spec.weight_format
    config_shape = {
        "num_experts": spec.num_experts,
        "hidden_size": spec.hidden_size,
        "intermediate_size": spec.intermediate_size,
        "dtype": config_dtype,
    }
    if has_cute_moe_config(**config_shape, num_tokens=capacity.max_tokens):
        return capacity
    if not has_cute_moe_config(**config_shape, num_tokens=None):
        return _resolve_power_of_two_prefill_capacity(capacity)

    resolve_capacity = (
        resolve_cute_moe_prefill_capacity
        if capacity.mode == "prefill"
        else resolve_cute_moe_exact_capacity
    )
    exact_capacity = resolve_capacity(capacity.max_tokens, **config_shape)
    if exact_capacity is None or exact_capacity == capacity.max_tokens:
        return capacity
    return replace(capacity, max_tokens=exact_capacity)


def _resolve_power_of_two_prefill_capacity(capacity: MoeCapacity) -> MoeCapacity:
    if capacity.mode != "prefill":
        return capacity
    return replace(
        capacity,
        max_tokens=1 << (capacity.max_tokens - 1).bit_length(),
    )


def _prepare_fresh(
    spec: MoeSpec,
    capacity: MoeCapacity,
    *,
    device: torch.device,
) -> MoeHandle:
    if device.type == "mps":
        if spec.activation == "geglu":
            raise NotImplementedError("geglu MoE is not implemented on MPS")
        from kestrel_kernels.mps import moe as mps_moe

        impl = mps_moe.prepare_compact_mps(spec, capacity, device)
        return MoeHandle(spec=spec, capacity=capacity, device=device, impl=impl)

    if device.type != "cuda":
        raise ValueError("MoE handles can only be prepared for CUDA or MPS devices")

    config_dtype = "fp8" if spec.weight_format == "fp8_e4m3" else spec.weight_format
    moe_config = None
    if has_cute_moe_config(
        num_experts=spec.num_experts,
        hidden_size=spec.hidden_size,
        intermediate_size=spec.intermediate_size,
        dtype=config_dtype,
        num_tokens=capacity.max_tokens,
    ):
        moe_config = get_cute_moe_config(
            capacity.max_tokens,
            num_experts=spec.num_experts,
            hidden_size=spec.hidden_size,
            intermediate_size=spec.intermediate_size,
            dtype=config_dtype,
        )
        up_kernel = moe_config["up"].kernel_type
        down_kernel = moe_config["down"].kernel_type
        if up_kernel == down_kernel == "warpgemv" and (
            config_dtype == "bf16" or spec.activation == "gelu"
        ):
            impl = prepare_warpgemv(spec, capacity, device, moe_config["up"])
            return MoeHandle(spec=spec, capacity=capacity, device=device, impl=impl)
        if spec.activation != "gelu" and (
            _gelu_only_kernel(up_kernel, dtype=config_dtype)
            or _gelu_only_kernel(down_kernel, dtype=config_dtype)
        ):
            if config_dtype == "fp8":
                raise ValueError(FP8_MOE_REQUIRES_COMPACT_CONFIG)
            raise ValueError(
                f"MoE activation {spec.activation!r} requires activation-aware kernels"
            )
        block_scheduled = (
            config_dtype == "fp8"
            and is_block_scheduled_fp8_kernel(up_kernel)
            and is_block_scheduled_fp8_kernel(down_kernel)
        )
        compact_kernels = up_kernel == down_kernel == "tcgen" or block_scheduled
        if compact_kernels:
            if spec.top_k == 8:
                impl = prepare_compact_moe(spec, capacity, device, moe_config)
                return MoeHandle(spec=spec, capacity=capacity, device=device, impl=impl)
            if config_dtype == "fp8":
                raise ValueError("compact MoE currently supports top_k=8")
            # BF16 has a valid padded implementation for other routing widths.
        if not compact_kernels and (
            "tcgen" in (up_kernel, down_kernel)
            or (
                config_dtype == "fp8"
                and any(
                    is_block_scheduled_fp8_kernel(k)
                    for k in (up_kernel, down_kernel)
                )
            )
        ):
            raise ValueError("compact MoE kernels must be selected for both up and down")
    if config_dtype == "fp8":
        from kestrel_kernels.cute_moe.config import (
            PORTABLE_FP8_WARP_CONFIG, has_exact_cute_moe_config,
        )
        # A portable implementation can admit a new shape, but cannot replace
        # a missing row of an existing measured selector or hide stale evidence.
        if _device_sm(device) == 120 and not has_exact_cute_moe_config(
            num_experts=spec.num_experts, hidden_size=spec.hidden_size,
            intermediate_size=spec.intermediate_size, dtype="fp8", num_tokens=None,
        ):
            if spec.hidden_size % 64 or spec.intermediate_size % 64:
                raise ValueError("portable FP8 MoE requires dimensions divisible by 64")
            impl = prepare_compact_moe(spec, capacity, device, {
                "up": PORTABLE_FP8_WARP_CONFIG, "down": PORTABLE_FP8_WARP_CONFIG,
            })
            return MoeHandle(spec=spec, capacity=capacity, device=device, impl=impl)
        raise ValueError(FP8_MOE_REQUIRES_COMPACT_CONFIG)
    sm = _device_sm(device)
    if config_dtype == "bf16" and sm in (90, 100):
        if moe_config is None:
            raise ValueError(
                f"sm_{sm} BF16 MoE requires an exact generated native config"
            )
        legacy_native_kernels = {"warp", "wgmma"} if sm == 90 else {"warp"}
        if up_kernel != down_kernel or up_kernel not in legacy_native_kernels:
            raise ValueError(
                f"sm_{sm} BF16 MoE requires matching native legacy kernels "
                "after WarpGEMV and TCGen selection"
            )

    from kestrel_kernels.gelu_residual import gelu_residual_cute
    from kestrel_kernels.moe_align import moe_align_block_size
    from kestrel_kernels.moe_dispatch import get_moe_block_m, invoke_moe_gemm
    from kestrel_kernels.moe_sum_ops import moe_sum

    ops = LegacyPaddedOps(
        gelu_residual_cute,
        get_moe_block_m,
        invoke_moe_gemm,
        moe_align_block_size,
        moe_sum,
    )

    impl = prepare_legacy_padded(
        spec, capacity, device,
        ops=ops,
    )
    return MoeHandle(spec=spec, capacity=capacity, device=device, impl=impl)


def forward(
    handle: MoeHandle,
    *,
    x: torch.Tensor,
    topk_ids: torch.Tensor,
    topk_weights: torch.Tensor,
    weights: MoeExpertWeights,
    out: torch.Tensor | None = None,
    lora: MoeLoraState | None = None,
    base_up_out: torch.Tensor | None = None,
) -> torch.Tensor:
    """Run MoE forward.

    ``base_up_out`` is optionally populated with the base up projection before
    LoRA is applied. It is intended for LoRA training/checkpointing and is only
    available on paths where ``lora`` is provided.
    """
    if base_up_out is not None and lora is None:
        raise ValueError("base_up_out is only available when lora is provided")
    tokens = int(x.shape[0])
    chunk_tokens = int(handle.capacity.max_tokens)
    if tokens > chunk_tokens:
        if handle.capacity.mode != "prefill":
            raise ValueError(
                f"MoE handle capacity overflow: got {tokens} tokens, "
                f"capacity is {chunk_tokens}"
            )
        if lora is not None:
            raise NotImplementedError(
                "chunked MoE prefill with LoRA requires metadata slicing"
            )
        if out is None:
            out = torch.empty_like(x)
        elif out.shape != x.shape:
            raise ValueError(
                f"MoE output shape {tuple(out.shape)} does not match input "
                f"shape {tuple(x.shape)}"
            )
        for start in range(0, tokens, chunk_tokens):
            end = min(start + chunk_tokens, tokens)
            output_chunk = out[start:end]
            result = handle.impl.forward(
                x=x[start:end],
                topk_ids=topk_ids[start:end],
                topk_weights=topk_weights[start:end],
                weights=weights,
                out=output_chunk,
                lora=None,
                base_up_out=None,
            )
            if result.data_ptr() != output_chunk.data_ptr():
                output_chunk.copy_(result)
        return out
    return handle.impl.forward(
        x=x,
        topk_ids=topk_ids,
        topk_weights=topk_weights,
        weights=weights,
        out=out,
        lora=lora,
        base_up_out=base_up_out,
    )


__all__ = ["forward", "prepare"]
